import re

def norm(s):
    return ''.join(ch.lower() for ch in s if ch.isalnum() or ch.isspace()).strip()


def search_all_songs(query, page_limit=20, sort_by=None):
    results=[]
    page_index=0
    while True:
        if sort_by is None:
            page = apis.spotify.search_songs(query=query, page_index=page_index, page_limit=page_limit)
        else:
            page = apis.spotify.search_songs(query=query, page_index=page_index, page_limit=page_limit, sort_by=sort_by)
        print('  search page', page_index, 'returned', len(page))
        if not page:
            break
        results.extend(page)
        page_index += 1
    return results


def select_song_id(entry):
    title = entry['title']
    expected_artists = entry['artists']
    # Build a search query using title + all expected artists
    q = ' '.join([title] + expected_artists) if expected_artists else title
    print('\nSelecting for:', entry['raw'])
    print('Search query:', q)

    all_results = search_all_songs(q, page_limit=20)
    print('Total results retrieved:', len(all_results))

    title_norm = norm(title)
    # Filter exact title matches
    title_matches = [r for r in all_results if norm(r.get('title',''))==title_norm]
    print('Title exact matches:', len(title_matches))

    expected_norm_artists = [norm(a) for a in expected_artists]
    exp_set = set(expected_norm_artists)

    def artists_set(r):
        return set(norm(a['name']) for a in r.get('artists', []) if 'name' in a and a['name'])

    strict = []
    for r in title_matches:
        if artists_set(r) == exp_set:
            strict.append(r)

    print('Strict artist-set matches:', len(strict))
    chosen = None

    if len(strict)==1:
        chosen = strict[0]
    elif len(title_matches)==1:
        chosen = title_matches[0]
    elif len(strict)>1:
        # If multiple strict matches, show and do not guess.
        print('AMBIGUITY: multiple strict matches for title+artists. ids/titles:')
        for r in strict:
            print('   ', r.get('song_id'), r.get('title'), [a['name'] for a in r.get('artists',[])])
    elif len(title_matches)>1:
        print('AMBIGUITY: multiple title matches, cannot disambiguate without unique artist match.')
        for r in title_matches[:5]:
            print('   ', r.get('song_id'), r.get('title'), [a['name'] for a in r.get('artists',[])])

    return chosen, {'query': q, 'all_results': len(all_results), 'title_matches': len(title_matches), 'strict_matches': len(strict)}


